from django.core.management.base import BaseCommand

from axes.utils import reset

class Command(BaseCommand):
    help = ("resets any lockouts or failed login records. If called with an "
            "IP, resets only for that IP")

    def add_arguments(self, parser):
        parser.add_argument('ip', nargs='*')

    def handle(self, *args, **kwargs):
        count = 0
        if kwargs:
            for ip in kwargs['ip']:
                count += reset(ip=ip)
        else:
            count = reset()

        if count:
            print('{0} attempts removed.'.format(count))
        else:
            print('No attempts found.')
```

### Notes

- I use nargs='*' now instead of '+'. '+' forces the user to provide at least one IP. Previously, I used nargs='?', which made the IP an optional param.
- The original phrase 'positional arg' makes me wonder if there's a better way to handle optional-ness. Are there/r are some gotchas? The current way seems okay.

